              _int_bit_mask_T_65,
              _int_bit_mask_T_70,
              _int_bit_mask_T_75,
              _int_bit_mask_T_80,
              _int_bit_mask_T_85,
              _int_bit_mask_T_90,
              _int_bit_mask_T_95,
              _int_bit_mask_T_100,
              _int_bit_mask_T_105,
              _int_bit_mask_T_110,
              _int_bit_mask_T_115})) | (|_int_bit_predicted_T_1);
  assign io_out_sig_raw = _a_minus_b_T_4[24:0];
